# 推斷：資料表=上期報價/本期報價（表頭第1列）｜欄位=品號、品名、單價、幣別、計價單位｜主檔=品號｜鍵=品號｜篩選=新增/刪除｜輸出=新工作表「增刪對照表」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws_prev = wb['上期報價']
ws_curr = wb['本期報價']

# 建立品號到整行資料的對映（保留原表順序）
prev_items = {}
for row in ws_prev.iter_rows(min_row=2, values_only=True):
    if row[0] is not None:
        prev_items[row[0]] = row

curr_items = {}
for row in ws_curr.iter_rows(min_row=2, values_only=True):
    if row[0] is not None:
        curr_items[row[0]] = row

prev_set = set(prev_items.keys())
curr_set = set(curr_items.keys())

# 新增工作表（若已存在則先移除）
if '增刪對照表' in wb.sheetnames:
    del wb['增刪對照表']
ws_new = wb.create_sheet('增刪對照表')

# 寫入表頭
headers = ['差異類型', '品號', '品名', '單價', '幣別', '計價單位']
ws_new.append(headers)

# 刪除：上期有，本期無
for pno, row in prev_items.items():
    if pno not in curr_set:
        ws_new.append(['刪除'] + list(row))

# 新增：本期有，上期無
for pno, row in curr_items.items():
    if pno not in prev_set:
        ws_new.append(['新增'] + list(row))

wb.save(OUTPUT_PATH)
