```python
# 推斷：資料表=上期報價與本期報價（表頭第1列）｜欄位=品號、品名、單價、幣別、計價單位｜主檔=上期報價、本期報價｜鍵=品號｜篩選=比較兩期差異（新增、刪除、修改）｜輸出=新工作表「增刪對照表」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws_prev = wb['上期報價']
ws_curr = wb['本期報價']

# 建立品號到資料的映射
prev_data = {}
for row in ws_prev.iter_rows(min_row=2, values_only=True):
    if row[0] is not None:
        prev_data[row[0]] = row[1:]  # 品名、單價、幣別、計價單位

curr_data = {}
for row in ws_curr.iter_rows(min_row=2, values_only=True):
    if row[0] is not None:
        curr_data[row[0]] = row[1:]

# 找出差異
diff_rows = []
# 刪除：上期有，本期沒有
for key in prev_data:
    if key not in curr_data:
        diff_rows.append(('刪除', key, *prev_data[key]))
# 新增：本期有，上期沒有
for key in curr_data:
    if key not in prev_data:
        diff_rows.append(('新增', key, *curr_data[key]))
# 修改：兩者都有，但其他欄位不同
for key in prev_data:
    if key in curr_data and prev_data[key] != curr_data[key]:
        diff_rows.append(('修改', key, *curr_data[key]))

# 建立新工作表
if '增刪對照表' in wb.sheetnames:
    del wb['增刪對照表']
ws_new = wb.create_sheet('增刪對照表')

# 寫入表頭
ws_new.append(['差異類型', '品號', '品名', '單價', '幣別', '計價單位'])

# 寫入資料
for row in diff_rows:
    ws_new.append(row)

wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=系統帳與實盤（表頭第1列）｜欄位=料號、品名、數量、儲位、單位｜主檔=系統帳｜鍵=料號｜篩選=系統帳有實盤無(刪除)、實盤有系統帳無(新增)｜輸出=新工作表「增刪對照表」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws_sys = wb['系統帳']
ws_actual = wb['實盤']

# 建立新工作表
ws_diff = wb.create_sheet('增刪對照表')

# 寫入表頭
headers = ['差異類型', '料號', '品名', '數量', '儲位', '單位']
ws_diff.append(headers)

# 收集系統帳料號與資料
sys_items = {}
for row in ws_sys.iter_rows(min_row=2, values_only=True):
    if row[0] is not None:
        sys_items[row[0]] = row[1:]  # 品名,數量,儲位,單位

# 收集實盤料號與資料
actual_items = {}
for row in ws_actual.iter_rows(min_row=2, values_only=True):
    if row[0] is not None:
        actual_items[row[0]] = row[1:]

# 找出刪除（系統帳有，實盤無）
for item_no, data in sys_items.items():
    if item_no not in actual_items:
        ws_diff.append(['刪除', item_no] + list(data))

# 找出新增（實盤有，系統帳無）
for item_no, data in actual_items.items():
    if item_no not in sys_items:
        ws_diff.append(['新增', item_no] + list(data))

wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=上月名冊/本月名冊（表頭第1列）｜欄位=員工編號,姓名,時數,部門,職稱｜主檔=員工編號｜鍵=員工編號｜篩選=兩表共有員工之欄位值差異｜輸出=新工作表「變更明細」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws_prev = wb['上月名冊']
ws_curr = wb['本月名冊']

# 讀取表頭（兩表表頭一致）
headers = [cell.value for cell in ws_prev[1]]  # ['員工編號', '姓名', '時數', '部門', '職稱']

# 建立上月資料字典：員工編號 -> {欄位: 值}
prev_data = {}
for row in ws_prev.iter_rows(min_row=2, values_only=True):
    emp_id = row[0]
    if emp_id is None:
        continue
    prev_data[emp_id] = {headers[i]: row[i] for i in range(1, len(headers))}

# 建立本月資料字典
curr_data = {}
for row in ws_curr.iter_rows(min_row=2, values_only=True):
    emp_id = row[0]
    if emp_id is None:
        continue
    curr_data[emp_id] = {headers[i]: row[i] for i in range(1, len(headers))}

# 找出共同員工編號
common_ids = set(prev_data.keys()) & set(curr_data.keys())

# 收集變更記錄
changes = []
for emp_id in sorted(common_ids):
    prev_row = prev_data[emp_id]
    curr_row = curr_data[emp_id]
    for field in headers[1:]:  # 姓名、時數、部門、職稱
        old_val = prev_row.get(field)
        new_val = curr_row.get(field)
        if old_val != new_val:
            changes.append((emp_id, field, old_val, new_val))

# 建立新工作表
if '變更明細' in wb.sheetnames:
    del wb['變更明細']
ws_new = wb.create_sheet('變更明細')
ws_new.append(['員工編號', '變更欄位', '舊值', '新值'])
for change in changes:
    ws_new.append(change)

wb.save(OUTPUT_PATH)
```
